import{_ as t,c as a,o as s,a3 as n}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Warehouses and locations","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/warehouses/index.md","filePath":"master/supply-chain/inventories/warehouses/index.md","lastUpdated":1793074831000}'),o={name:"master/supply-chain/inventories/warehouses/index.md"};function r(i,e,l,p,h,c){return s(),a("div",null,e[0]||(e[0]=[n(`<h1 id="warehouses-and-locations" tabindex="-1">Warehouses and locations <a class="header-anchor" href="#warehouses-and-locations" aria-label="Permalink to &quot;Warehouses and locations&quot;">​</a></h1><p>Stock always sits somewhere. Aureus describes &quot;somewhere&quot; with four building blocks: warehouses, locations, operation types and storage categories. This group explains each one and how they fit together, so the transfers you create later make sense.</p><blockquote><p><strong>In simple words:</strong> A warehouse is the building, locations are the shelves and zones inside it, and operation types are the kinds of job you do between them.</p></blockquote><h2 id="how-the-pieces-relate" tabindex="-1">How the pieces relate <a class="header-anchor" href="#how-the-pieces-relate" aria-label="Permalink to &quot;How the pieces relate&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Building block</th><th>What it is</th><th>Example</th></tr></thead><tbody><tr><td><strong>Warehouse</strong></td><td>A physical site that holds stock. It has a short name that prefixes its locations.</td><td>My Company, short name <strong>WH</strong></td></tr><tr><td><strong>Location</strong></td><td>A named place where stock can be. Locations sit inside each other like folders.</td><td><strong>WH/Stock</strong>, <strong>WH/Input</strong></td></tr><tr><td><strong>Operation type</strong></td><td>A kind of job, such as a receipt or a delivery. It sets the document prefix and the default from and to locations.</td><td><strong>Receipts</strong>, prefix <strong>IN</strong></td></tr><tr><td><strong>Storage category</strong></td><td>A rule set for a location: how much weight, packages or products it may hold.</td><td>A pallet rack with a 500 kg limit</td></tr></tbody></table><p>The tree below shows the example warehouse after you choose three-step reception and delivery.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Physical Locations</span></span>
<span class="line"><span>└── WH  (warehouse, type View)</span></span>
<span class="line"><span>    ├── Stock          (Internal)</span></span>
<span class="line"><span>    ├── Input          (Internal)</span></span>
<span class="line"><span>    ├── Quality Control(Internal)</span></span>
<span class="line"><span>    ├── Output         (Internal)</span></span>
<span class="line"><span>    └── Packing Zone   (Internal)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Partners</span></span>
<span class="line"><span>├── Vendors            (Vendor)</span></span>
<span class="line"><span>└── Customers          (Customer)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Virtual Locations</span></span>
<span class="line"><span>├── Inventory Adjustment (Inventory Loss)</span></span>
<span class="line"><span>├── Production           (Production)</span></span>
<span class="line"><span>└── Scrap                (Inventory Loss)</span></span></code></pre></div><p>Every stock move goes from one location to another. A receipt moves goods from <strong>Partners/Vendors</strong> to <strong>WH/Stock</strong>. A delivery moves them from <strong>WH/Stock</strong> to <strong>Partners/Customers</strong>. The operation type decides which pair of locations a document starts with.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ul><li><a href="./warehouses.html">Warehouses</a>: create a warehouse and choose its reception and delivery steps.</li><li><a href="./locations.html">Locations</a>: build the location tree and set the type of each place.</li><li><a href="./operation-types.html">Operation types</a>: see the 14 ready-made job types and what each setting does.</li><li><a href="./storage-categories.html">Storage categories</a>: limit what a location can hold.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Locations menu appears only when <strong>Locations</strong> is on in <code>Inventory → Settings → Manage Warehouses</code>. Storage categories and the extra step options need <strong>Multi Steps Routes</strong> in the same page. See <a href="./../get-started/inventory-settings.html">Inventory settings</a>.</p></div><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ol><li>Open <a href="./warehouses.html">Warehouses</a> and check the short name and the step options.</li><li>Read <a href="./locations.html">Locations</a> to understand the tree and the location types.</li><li>Use <a href="./operation-types.html">Operation types</a> when you need to change a prefix or a default location.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../get-started/inventory-overview.html">Inventory overview</a></li><li><a href="./../operations/">Operations</a></li><li><a href="./../routes/">Routes</a></li></ul>`,15)]))}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
